using System;using System.Drawing;using System.Collections.Generic;using System.Linq;
namespace Synkoz {
 internal sealed partial class GraphRun15 {
  List<GraphEvent15> LumaEventsR4(GraphNode15 node){var values=new List<GraphEvent15>();if(!videoOrder.Any(n=>n.Id==node.Id)||node.MutedR4||!fx.Graph15.Wires.Any(w=>w.From==node.Id&&w.Port==GraphPort15.Trigger))return values;var subset=UiR2.Copy(fx);var ids=new HashSet<string>();Action<string> visit=null;visit=id=>{if(!ids.Add(id))return;foreach(var w in subset.Graph15.Wires.Where(w=>w.To==id))visit(w.From);};foreach(var w in subset.Graph15.Wires.Where(w=>w.To==node.Id))visit(w.From);subset.Graph15.Nodes.RemoveAll(n=>!ids.Contains(n.Id));subset.Graph15.Wires.RemoveAll(w=>!ids.Contains(w.From)||!ids.Contains(w.To));var output=new GraphNode15{Kind=GraphKind15.Output};subset.Graph15.Nodes.Add(output);foreach(var w in fx.Graph15.Wires.Where(w=>w.To==node.Id&&w.Port==GraphPort15.Video))subset.Graph15.Wires.Add(new GraphWire15{From=w.From,To=output.Id,Port=GraphPort15.Video,Order=w.Order});double last=double.NaN;using(var run=new GraphRun15(subset,model,media))using(var blank=new Bitmap(160,90))for(int i=0;i<Math.Ceiling(model.Duration*30);i++){double t=i/30.0;using(var image=run.Render(blank,t)){double level=Math.Max(0,Math.Min(1,TboSignal15.Luminance(image,node)*node.Gain+node.Bias));if(level!=last)values.Add(new GraphEvent15{Origin=node.Id,Identity=node.Id+":"+i,Kind="CC",CC=node.ControlCC,Channel=node.ChannelR4%16,Track=node.ChannelR4>=16?node.ChannelR4+1:-1,Value=level,Bits=64,Time=t,End=t});last=level;}}return values;}
  List<GraphEvent15> AudioEventsR4(GraphNode15 n){var list=new List<GraphEvent15>();var wire=fx.Graph15.Wires.Where(w=>w.To==n.Id&&w.Port==GraphPort15.Audio).OrderBy(w=>w.Order).LastOrDefault();if(!videoOrder.Any(v=>v.Id==n.Id)||media==null||wire==null||n.MutedR4)return list;var source=fx.Graph15.Nodes.First(s=>s.Id==wire.From);if(source.MutedR4)return list;bool armed=true;double previous=double.NaN;for(int i=0;i<Math.Ceiling(model.Duration*100);i++){double t=i*.01,v=Math.Max(0,Math.Min(1,media.Level(source.MediaTrack,t)*n.Gain+n.Bias));if(n.Kind==GraphKind15.AudioToControl){if(v!=previous)list.Add(new GraphEvent15{Origin=n.Id,Identity=n.Id+":"+i,Kind="CC",CC=n.ControlCC,Channel=n.ChannelR4%16,Track=n.ChannelR4>=16?n.ChannelR4+1:-1,Time=t,End=t,Value=v,Bits=64});previous=v;}else{if(v<=n.RearmAudioR4)armed=true;if(armed&&v>=n.ThresholdAudioR4){list.Add(new GraphEvent15{Origin=n.Id,Identity=n.Id+":"+i,Kind="NoteOn",Note=n.NoteR4,Velocity=Math.Max(1,(int)Math.Round(v*127)),Channel=n.ChannelR4%16,Track=n.ChannelR4>=16?n.ChannelR4+1:-1,Time=t,End=t+n.NoteLengthR4,Value=n.NoteR4,Bits=7});armed=false;}}}foreach(var on in list.Where(e=>e.Kind=="NoteOn").ToArray()){var off=on.Copy();off.Kind="NoteOff";off.Time=off.End;off.Velocity=0;off.Identity+="/off";list.Add(off);}return list.OrderBy(e=>e.Time).ToList();}
 }
}
